/* @lc app=leetcode id=2569 lang=kotlin */ class Solution { fun ap(c: IntArray, lz: BooleanArray, o: Int, l: Int, r: Int) = c.set(o, r - l + 1 - c[o]).also { lz[o] = !lz[o] } fun build(a: IntArray, c: IntArray, o: Int, l: Int, r: Int): Unit = if (l == r) c.set(o, a[l]) else ((l + r) / 2).let { m -> build(a, c, 2 * o, l, m).also { build(a, c, 2 * o + 1, m + 1, r) }.also { c[o] = c[2 * o] + c[2 * o + 1] } } fun flip(c: IntArray, lz: BooleanArray, o: Int, l: Int, r: Int, a: Int, b: Int): Unit = if (a <= l && r <= b) ap(c, lz, o, l, r) else ((l + r) / 2).let { m -> (if (lz[o]) ap(c, lz, 2 * o, l, m).also { ap(c, lz, 2 * o + 1, m + 1, r) }.also { lz[o] = false } else Unit).also { if (a <= m) flip(c, lz, 2 * o, l, m, a, b) }.also { if (b > m) flip(c, lz, 2 * o + 1, m + 1, r, a, b) }.also { c[o] = c[2 * o] + c[2 * o + 1] } } fun handleQuery(nums1: IntArray, nums2: IntArray, queries: Array<IntArray>): LongArray = nums1.size.let { n -> IntArray(4 * n).let { c -> BooleanArray(4 * n).let { lz -> build(nums1, c, 1, 0, n - 1).let { nums2.sumOf { it.toLong() }.let { s0 -> queries.fold(s0 to listOf<Long>()) { (s, res), (t, p, q) -> if (t == 1) flip(c, lz, 1, 0, n - 1, p, q).let { s to res } else if (t == 2) (s + p.toLong() * c[1]) to res else s to res + s }.second.toLongArray() } } } } } }